mappages["poverty2"].onload = function(mapref) {
  if ((gamestate.getMode() !== "loadgame") && (!DU.gameflags.getFlag("editor"))) {
    if (!DU.gameflags.getFlag("visited_poverty2")) {
      mapmagic["poverty2"] = JSON.parse(JSON.stringify(mapmagic["poverty2"]));
      DU.gameflags.setFlag("visited_poverty2",1);
    }
    let npcs = mapref.npcs.getAll();
    if (!DU.gameflags.getFlag("anna_return")) { 
      let anna;
      for (let i=0;i<npcs.length;i++) {
        if (npcs[i].getNPCName() === "Anna") { anna = npcs[i]; }
      }
      if (anna) {
        mapref.deleteThing(anna);
        DUTime.removeEntityFrom(anna);
      }
    } else {
      let brooke;
      for (let i=0;i<npcs.length;i++) {
        if (npcs[i].getNPCName() === "Brooke") { brooke = npcs[i]; }
      }
      if (brooke) {
        brooke.setSchedule("brooke2");
        let loc = DU.schedules["brooke2"].getNPCLocationByTime(GetClockTime(), 1, 1, mapref, brooke);
        mapref.moveThing(loc.x,loc.y,brooke);
        let brooketile = mapref.getTile(loc.x,loc.y);
        brooketile.executeWalkons(brooke);
        brooke.startx = loc.x;
        brooke.starty = loc.y
      }
    }
    if (!DU.gameflags.getFlag("beldskae_razed")) {
      let kath;
      let graham;
      for (let i=0;i<npcs.length;i++) {
        if (npcs[i].getNPCName() === "Kathleen") { kath = npcs[i]; }
        if (npcs[i].getNPCName() === "Graham") { graham = npcs[i]; }
      }
      mapref.deleteThing(kath);
      DUTime.removeEntityFrom(kath);
      mapref.deleteThing(graham);
      DUTime.removeEntityFrom(graham);
    }
  }
}
